# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">RİSALET ÖNCESİ CAHİLİYE ORTAMI VE HZ. MUHAMMED\'İN (SAV) ERDEMLİ DURUŞU</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#991b1b">CAHİLİYE TOPLUMUNUN KARANLIK YÜZÜ</text>\n  <text x="34" y="88" font-size="10.8" fill="#7f1d1d">• <tspan font-weight="bold">İnançta Şirk:</tspan> Kâbe ve çevresini 360 putla doldurma,</text>\n  <text x="44" y="104" font-size="10.4" fill="#7f1d1d">putları Allah ile kul arasında şefaatçi görme.</text>\n  <text x="34" y="126" font-size="10.8" fill="#7f1d1d">• <tspan font-weight="bold">Kabilecilik (Asabiyet):</tspan> Zalim de olsa kabiledaşını</text>\n  <text x="44" y="142" font-size="10.4" fill="#7f1d1d">savunma ve yıllarca süren Eyyâmü\'l-Arab savaşları.</text>\n  <text x="34" y="164" font-size="10.8" fill="#7f1d1d">• <tspan font-weight="bold">Sosyal Zulüm:</tspan> Kadınların, yetimlerin, kölelerin ve</text>\n  <text x="44" y="180" font-size="10.4" fill="#7f1d1d">yabancıların haklarının gasp edilmesi; riba (faiz).</text>\n  <text x="34" y="202" font-size="10.8" fill="#7f1d1d">• İçki, kumar, fal okları ve panayır kavgaları.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#166534">HZ. MUHAMMED\'İN (SAV) NEZİH HAYATI (İSMET)</text>\n  <text x="370" y="88" font-size="10.8" fill="#14532d">• <tspan font-weight="bold">Tevhit Fıtratı:</tspan> Putlara tapmamış, putlar adına</text>\n  <text x="380" y="104" font-size="10.4" fill="#14532d">kesilen kurban etlerinden yememiştir.</text>\n  <text x="370" y="126" font-size="10.8" fill="#14532d">• <tspan font-weight="bold">Ahlaki Temizlik:</tspan> İçki, kumar, yalan ve kötü sözden</text>\n  <text x="380" y="142" font-size="10.4" fill="#14532d">daima uzak durmuş; \'Muhammedü\'l-Emîn\' bilindi.</text>\n  <text x="370" y="164" font-size="10.8" fill="#14532d">• <tspan font-weight="bold">Adalet ve Merhamet:</tspan> Hilfü\'l-Fudûl\'e katılmış,</text>\n  <text x="380" y="180" font-size="10.4" fill="#14532d">Kâbe Hakemliği ile toplumsal barışı sağlamıştır.</text>\n  <text x="370" y="202" font-size="10.8" font-weight="bold" fill="#15803d">• İlahi koruma (İsmet) ile risalete hazırlanmıştır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Muhammed\'in (sav) risalet öncesi 40 yıllık tertemiz hayatı, peygamberliğinin en güçlü doğruluk delilidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">RİSALETE DOĞRU: SADIK RÜYALAR, HİRA\'DA TAHANNÜS VE İLK VAHİY (610)</text>\n  <rect x="22" y="42" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#1e40af">1. SADIK RÜYALAR</text>\n  <text x="32" y="88" font-size="10.4" fill="#1e3a8a">• Risaletten önceki 6 ay</text>\n  <text x="38" y="104" font-size="10.4" fill="#1e3a8a">boyunca uykuda gördüğü</text>\n  <text x="38" y="120" font-size="10.4" fill="#1e3a8a">doğru rüyalar (rü\'yâ-yı sâdıka).</text>\n  <text x="32" y="144" font-size="10.4" fill="#1e3a8a">• Gördüğü her rüya sabah</text>\n  <text x="38" y="160" font-size="10.4" fill="#1e3a8a">aydınlığı gibi birebir</text>\n  <text x="38" y="176" font-size="10.4" fill="#1e3a8a">gerçekleşmiştir.</text>\n  <text x="32" y="198" font-size="10.4" font-weight="bold" fill="#1d4ed8">• Vahye ruhsal hazırlık.</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#854d0e">2. HİRA\'DA İNZİVA (TAHANNÜS)</text>\n  <text x="255" y="88" font-size="10.4" fill="#713f12">• Mekke\'nin kuzeydoğusundaki</text>\n  <text x="261" y="104" font-size="10.4" fill="#713f12">Nur Dağı (Cebel-i Nûr) Hira</text>\n  <text x="261" y="120" font-size="10.4" fill="#713f12">Mağarası\'nda halvet.</text>\n  <text x="255" y="144" font-size="10.4" fill="#713f12">• Özellikle Ramazan aylarında</text>\n  <text x="261" y="160" font-size="10.4" fill="#713f12">şirk ortamından uzaklaşıp</text>\n  <text x="261" y="176" font-size="10.4" fill="#713f12">kâinatı tefekkür ve ibadet.</text>\n  <text x="255" y="198" font-size="10.4" font-weight="bold" fill="#a16207">• Yoksulları doyurma ve tavaf.</text>\n  <rect x="468" y="42" width="210" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="573" y="64" text-anchor="middle" font-size="11.8" font-weight="bold" fill="#6b21a8">3. İLK VAHİY (610 RAMAZAN)</text>\n  <text x="478" y="88" font-size="10.4" fill="#581c87">• 40 yaşında Hira Mağarası\'nda</text>\n  <text x="484" y="104" font-size="10.4" fill="#581c87">Cebrâil (as) ile karşılaşma.</text>\n  <text x="478" y="128" font-size="10.4" font-weight="bold" fill="#7e22ce">• Alak Suresi 1-5. Ayetler:</text>\n  <text x="484" y="144" font-size="10.4" fill="#581c87">«Yaratan Rabbinin adıyla oku!»</text>\n  <text x="478" y="168" font-size="10.4" fill="#581c87">• Hz. Hatice\'nin tesellisi ve</text>\n  <text x="484" y="184" font-size="10.4" fill="#581c87">Varaka b. Nevfel ile görüşme.</text>\n  <text x="478" y="202" font-size="10.4" font-weight="bold" fill="#6b21a8">• Risalet döneminin başlaması.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Tahannüs: Hz. Muhammed\'in (sav) risalet öncesinde Hira Mağarası\'nda günlerce kalarak yaptığı tefekkür ve ibadettir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">1. ÜNİTE ÖZETİ: HZ. MUHAMMED\'İN (SAV) RİSALET ÖNCESİ 40 YILLIK HAYATI (571-610)</text>\n  <rect x="18" y="42" width="158" height="172" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="97" y="62" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#1e40af">DOĞUM VE ÇOCUKLUK</text>\n  <text x="28" y="84" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">571 (Fil Yılı):</tspan> Mekke\'de</text>\n  <text x="34" y="98" font-size="10" fill="#1e3a8a">doğumu (Abdullah ve Âmine).</text>\n  <text x="28" y="118" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">0-4 Yaş:</tspan> Sütannesi</text>\n  <text x="34" y="132" font-size="10" fill="#1e3a8a">Halîme\'nin yanında (Sa\'d yurdu).</text>\n  <text x="28" y="152" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">6 Yaş:</tspan> Annesi Âmine\'nin</text>\n  <text x="34" y="166" font-size="10" fill="#1e3a8a">Ebvâ\'da vefatı (Ümmü Eymen).</text>\n  <text x="28" y="186" font-size="10" fill="#1e3a8a">• <tspan font-weight="bold">8 Yaş:</tspan> Abdülmuttalib\'in</text>\n  <text x="34" y="200" font-size="10" fill="#1e3a8a">vefatı ve Ebû Tâlib himayesi.</text>\n  <rect x="186" y="42" width="158" height="172" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="265" y="62" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#166534">GENÇLİK VE ERDEMLER</text>\n  <text x="196" y="84" font-size="10" fill="#14532d">• Çobanlık ve amcasıyla</text>\n  <text x="202" y="98" font-size="10" fill="#14532d">ticaret seyahatleri.</text>\n  <text x="196" y="118" font-size="10" fill="#14532d">• <tspan font-weight="bold">20 Yaş (~590):</tspan> Ficâr</text>\n  <text x="202" y="132" font-size="10" fill="#14532d">Savaşı\'nda saldırganlıktan</text>\n  <text x="202" y="146" font-size="10" fill="#14532d">uzak durması.</text>\n  <text x="196" y="166" font-size="10" fill="#14532d">• <tspan font-weight="bold">Hilfü\'l-Fudûl (Erdemliler):</tspan></text>\n  <text x="202" y="180" font-size="10" fill="#14532d">Mazlumların hakkını koruyan</text>\n  <text x="202" y="194" font-size="10" fill="#14532d">antlaşmaya aktif katılımı.</text>\n  <rect x="354" y="42" width="158" height="172" rx="8" fill="#ffedd5" stroke="#ea580c" stroke-width="1.8"/>\n  <text x="433" y="62" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#9a3412">AİLE VE HAKEMLİK</text>\n  <text x="364" y="84" font-size="10" fill="#7c2d12">• <tspan font-weight="bold">Muhammedü\'l-Emîn:</tspan></text>\n  <text x="370" y="98" font-size="10" fill="#7c2d12">Ticarette mutlak güvenilirlik.</text>\n  <text x="364" y="118" font-size="10" fill="#7c2d12">• <tspan font-weight="bold">25 Yaş (595):</tspan> Hz. Hatice</text>\n  <text x="370" y="132" font-size="10" fill="#7c2d12">ile örnek evliliği ve</text>\n  <text x="370" y="146" font-size="10" fill="#7c2d12">6 çocuğu (Hz. Ali ve Zeyd).</text>\n  <text x="364" y="166" font-size="10" fill="#7c2d12">• <tspan font-weight="bold">35 Yaş (605):</tspan> Kâbe tamiri</text>\n  <text x="370" y="180" font-size="10" fill="#7c2d12">ve Hacerü\'l-Esved hakemliği</text>\n  <text x="370" y="194" font-size="10" fill="#7c2d12">ile kan davasını önlemesi.</text>\n  <rect x="522" y="42" width="160" height="172" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="602" y="62" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#6b21a8">RİSALETE DOĞRU (610)</text>\n  <text x="532" y="84" font-size="10" fill="#581c87">• Cahiliye şirkinden ve</text>\n  <text x="538" y="98" font-size="10" fill="#581c87">kötülüklerinden uzak duruş.</text>\n  <text x="532" y="118" font-size="10" fill="#581c87">• <tspan font-weight="bold">39-40 Yaş:</tspan> Altı ay süren</text>\n  <text x="538" y="132" font-size="10" fill="#581c87">sadık rüyalar (rü\'yâ-yı sâdıka).</text>\n  <text x="532" y="152" font-size="10" fill="#581c87">• <tspan font-weight="bold">Hira Mağarası:</tspan> Ramazan</text>\n  <text x="538" y="166" font-size="10" fill="#581c87">ayında inziva ve tefekkür</text>\n  <text x="538" y="180" font-size="10" fill="#581c87">(tahannüs) ve İlk Vahiy (610).</text>\n  <rect x="18" y="222" width="664" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="239" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">«Sen bundan önce kırk yıl aramızda bir ömür sürdün; hâlâ aklınızı kullanmayacak mısınız?» (Yûnus, 10/16)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
